        { id: 'terminalNode', label: 'Puestos POS x N · Nodo<br/>Sistema operativo por inventariar', nodes: ['client','device'] },
        { id: 'serverNode', label: 'Servidor de sucursal · Nodo<br/>Entorno de ejecución por homologar', nodes: ['branchApi','syncWorker','branchDb'] },
        { id: 'countryNode', label: 'Plataforma de país · Nodo<br/>Alojamiento por decidir', nodes: ['countryApi','countryWorker','erpAdapter','countryDb'] },
      ],
      relationships: [rel('client','branchApi','Comandos autenticados · HTTPS/LAN'),rel('client','device','Comando autorizado por backend · IPC/loopback por homologar'),rel('branchApi','branchDb','Negocio + outbox · SQL local'),rel('syncWorker','branchDb','Pendientes, cursores y espejo · SQL local'),rel('syncWorker','countryApi','Lotes, deltas y snapshots · HTTPS/WAN'),rel('countryApi','countryDb','Commit inbox + efecto + outbox antes de ACK · SQL'),rel('countryWorker','countryDb','Outbox confirmada / publicaciones · SQL'),rel('countryWorker','erpAdapter','Contrato canónico · HTTPS interno'),rel('erpAdapter','erp','Traducción por país · interfaz ERP por validar'),rel('erpAdapter','countryDb','Resultados y referencias · SQL'),rel('device','payments','Terminal/pago · SDK o API homologado'),rel('branchApi','fiscal','Emisión/transmisión · modalidad por homologar'),rel('branchDb','backup','Copia y evidencia de restore · mecanismo por definir'),rel('countryDb','backup','Copia y retención por país · mecanismo por definir')],
    },
  ];
  for (const view of views) view.nodeIds.push('legend');
  window.POS_C4 = {
    views, nodes, sources,
    legend: [
      'Persona: rol humano. Sistema externo: responsabilidad fuera del POS.',
      'Contenedor: aplicación/proceso o almacén de datos. Componente: módulo dentro de un proceso.',
      'Verde: software POS. Azul/cilindro: datos. Gris: externo. Borde discontinuo: límite del alcance.',
      'Cada flecha indica quién inicia la relación, con propósito y protocolo; la respuesta viaja por el mismo contrato.',
      'LAN: red de sucursal. WAN: enlace a país. ACL: capa anticorrupción. ACK: acuse de aplicación tras commit durable.',
      'Todo es propuesta salvo antecedentes expresamente señalados. Despliegue es complementario; no es el nivel C4 de código.',
    ],
  };
})();

